// Shared scaffolding for the a64 encoder dump tools.
//
// The AArch64 backend cannot be executed on an x86 host, so the migration is
// verified by comparing *generated bytes* instead of behaviour: the old
// hand-written encoder and the asmjit-based one must emit the same words for
// the same primitive call. tools/jit_matrix/a64_golden.txt holds the frozen
// output of the old encoder and a64_dump_new.cpp is diffed against it.
//
// arm64_emit.cpp is not a standalone translation unit: in the real build it is
// textually included by arm_jit_arm.cpp, which supplies `g_out`, `genlabel()`
// and `get_flags()`. This header provides the same handful of symbols so the
// file can be dumped on its own.

#pragma once

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef uint8_t u8;
typedef uint16_t u16;
typedef uint32_t u32;
typedef uint64_t u64;

#ifdef _WIN32
#include <windows.h>
// The dump only needs the encoder. emit_core reports a failed VirtualAlloc
// through a message box, which would drag user32 into an offline tool.
#define MessageBoxA(a, b, c, d) 0
#else
#include <sys/mman.h>
#endif

#include <map>
#include <vector>

// arm64_emit.cpp/emit_core.cpp call arm_jit_reset() when the 40MB block runs
// out. The dump only emits a few kilobytes, so this never fires.
void arm_jit_reset(int) {}

// Consumed by the flag helpers. The real definition lives in arm_jit_arm.cpp
// and is not touched by this migration, so the dump replaces it with a marker
// instruction: identical on both sides, and it keeps the position visible.
#define VALUE_NO_CACHE 2

// AArch64 `nop`, standing in for get_flags().
#define A64_DUMP_GET_FLAGS_MARKER 0xD503201Fu
